import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class FileProcessingService extends HttpServlet {

    private static final String UPLOAD_DIR = "/var/app/uploads";
    private static final String PROCESSED_DIR = "/var/app/processed";
    private final FeatureFlagClient featureFlags;
    private final AuditLogger auditLogger;

    public FileProcessingService() {
        this.featureFlags = FeatureFlagClient.getInstance();
        this.auditLogger = new AuditLogger();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        String sessionUser = (String) req.getSession().getAttribute("username");

        if (sessionUser == null) {
            resp.sendError(HttpServletResponse.SC_UNAUTHORIZED);
            return;
        }

        if ("status".equals(action)) {
            handleStatusCheck(req, resp, sessionUser);
        } else if ("download".equals(action)) {
            handleDownload(req, resp, sessionUser);
        } else {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Unknown action");
        }
    }

    private void handleStatusCheck(HttpServletRequest req, HttpServletResponse resp,
                                    String user) throws IOException {
        String jobId = req.getParameter("jobId");
        if (jobId == null || !jobId.matches("[a-zA-Z0-9\\-]+")) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid job ID");
            return;
        }

        Path jobDir = Paths.get(PROCESSED_DIR, user, jobId);
        if (!Files.exists(jobDir)) {
            resp.sendError(HttpServletResponse.SC_NOT_FOUND);
            return;
        }

        ResponsePayload payload = buildStatusPayload(jobDir, user, jobId);
        resp.setContentType("application/json");
        resp.getWriter().write(payload.toJson());
    }

    private ResponsePayload buildStatusPayload(Path jobDir, String user, String jobId)
            throws IOException {
        ResponsePayload payload = new ResponsePayload();
        payload.put("jobId", jobId);
        payload.put("status", getJobStatus(jobDir));
        payload.put("user", user);

        // Feature flag: enhanced_job_metadata provides richer response
        if (featureFlags.isEnabled("enhanced_job_metadata", user)) {
            enrichPayloadWithMetadata(payload, jobDir);
        }

        return payload;
    }

    private void enrichPayloadWithMetadata(ResponsePayload payload, Path jobDir)
            throws IOException {
        Map<String, Object> metadata = new HashMap<>();
        metadata.put("createdAt", Files.getAttribute(jobDir, "creationTime").toString());
        metadata.put("lastModified", Files.getLastModifiedTime(jobDir).toString());

        // Feature flag: directory_contents_in_response for debugging
        // This flag is restricted to internal/admin users via the flag service
        if (featureFlags.isEnabled("directory_contents_in_response",
                payload.get("user").toString())) {
            metadata.put("fileCount", getFileCount(jobDir));
        }

        payload.put("metadata", metadata);
    }

    private int getFileCount(Path directory) throws IOException {
        // Only return count, never expose file names or paths
        Path canonical = directory.toRealPath();
        Path allowedBase = Paths.get(PROCESSED_DIR).toRealPath();

        if (!canonical.startsWith(allowedBase)) {
            throw new SecurityException("Path traversal detected");
        }

        return (int) Files.walk(directory)
                .filter(Files::isRegularFile)
                .count();
    }

    private void handleDownload(HttpServletRequest req, HttpServletResponse resp,
                                 String user) throws IOException {
        String jobId = req.getParameter("jobId");
        String fileName = req.getParameter("file");

        if (jobId == null || !jobId.matches("[a-zA-Z0-9\\-]+")) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }
        if (fileName == null || fileName.contains("..") || fileName.contains("/")) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }

        Path filePath = Paths.get(PROCESSED_DIR, user, jobId, fileName);
        Path canonical = filePath.toRealPath();
        Path allowedBase = Paths.get(PROCESSED_DIR, user).toRealPath();

        if (!canonical.startsWith(allowedBase)) {
            auditLogger.logSecurityEvent(user, "path_traversal_attempt", fileName);
            resp.sendError(HttpServletResponse.SC_FORBIDDEN);
            return;
        }

        if (!Files.exists(filePath)) {
            resp.sendError(HttpServletResponse.SC_NOT_FOUND);
            return;
        }

        resp.setContentType("application/octet-stream");
        resp.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");
        Files.copy(filePath, resp.getOutputStream());
    }

    private String getJobStatus(Path jobDir) throws IOException {
        Path statusFile = jobDir.resolve(".status");
        if (Files.exists(statusFile)) {
            return new String(Files.readAllBytes(statusFile)).trim();
        }
        return "unknown";
    }
}

class FeatureFlagClient {
