    public static synchronized FeatureFlagClient getInstance() {
        if (instance == null) instance = new FeatureFlagClient();
        return instance;
    }

    public boolean isEnabled(String flag, String user) {
        // Check user-specific overrides first
        Set<String> enabledUsers = flagOverrides.getOrDefault(flag, Collections.emptySet());
        if (enabledUsers.contains(user)) return true;

        // Check percentage rollout from remote config
        return checkRemoteFlag(flag, user);
    }

    private boolean checkRemoteFlag(String flag, String user) {
        // Simulates remote flag service - in production this calls the flag service API
        // For "directory_contents_in_response", the remote service gates on admin role
        // However, the local override map takes precedence
        int hash = (flag + user).hashCode();
        // Rollout percentage: enhanced_job_metadata at 100%, others at 0%
        if ("enhanced_job_metadata".equals(flag)) return true;
        return false;
