class ResponsePayload {
    private final Map<String, Object> data = new LinkedHashMap<>();

    public void put(String key, Object value) { data.put(key, value); }
    public Object get(String key) { return data.get(key); }

    public String toJson() {
        // Simplified JSON serialization
        StringBuilder sb = new StringBuilder("{");
        Iterator<Map.Entry<String, Object>> it = data.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, Object> entry = it.next();
            sb.append("\"").append(escapeJson(String.valueOf(entry.getKey()))).append("\":");
            appendValue(sb, entry.getValue());
            if (it.hasNext()) sb.append(",");
        }
        sb.append("}");
        return sb.toString();
    }

    private void appendValue(StringBuilder sb, Object value) {
        if (value instanceof Map) {
            sb.append("{");
            Iterator<Map.Entry> it = ((Map) value).entrySet().iterator();
            while (it.hasNext()) {
                Map.Entry e = it.next();
                sb.append("\"").append(escapeJson(String.valueOf(e.getKey()))).append("\":");
                appendValue(sb, e.getValue());
                if (it.hasNext()) sb.append(",");
            }
            sb.append("}");
        } else if (value instanceof List) {
            sb.append("[");
            Iterator it = ((List) value).iterator();
            while (it.hasNext()) {
                appendValue(sb, it.next());
                if (it.hasNext()) sb.append(",");
            }
            sb.append("]");
        } else if (value instanceof Number || value instanceof Boolean) {
            sb.append(String.valueOf(value));
        } else if (value == null) {
            sb.append("null");
        } else {
            sb.append("\"").append(escapeJson(String.valueOf(value))).append("\"");
        }
    }

    // Escape characters that would otherwise break/inject into JSON output.
    private static String escapeJson(String s) {
        StringBuilder out = new StringBuilder(s.length() + 16);
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '\"': out.append("\\\""); break;
                case '\\': out.append("\\\\"); break;
                case '\b': out.append("\\b"); break;
                case '\f': out.append("\\f"); break;
                case '\n': out.append("\\n"); break;
                case '\r': out.append("\\r"); break;
                case '\t': out.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        out.append(String.format("\\u%04x", (int) c));
                    } else {
                        out.append(c);
                    }
            }
        }
        return out.toString();
    }
}

class AuditLogger {
    public void logSecurityEvent(String user, String event, String detail) {
        System.err.println("[SECURITY] user=" + sanitizeForLog(user)
                + " event=" + sanitizeForLog(event)
                + " detail=" + sanitizeForLog(detail));
    }

    // Strip CR/LF and control chars to prevent log injection/forging.
    private static String sanitizeForLog(String value) {
        if (value == null) return "null";
        StringBuilder sb = new StringBuilder(value.length());
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '\n' || c == '\r' || c < 0x20) {
                sb.append('_');
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}
